// La salida 'done' del loop trae un item por medio con la marca de si el proveedor lo
// acepto. El resumen se redacta como instruccion para el agente, no como dato:
// es lo unico que el modelo va a leer sobre lo que acaba de pasar.
const items = $input.all().map((i) => i.json);
const enviados = items.filter((i) => i.enviado).map((i) => i.descripcion);
const fallidos = items.filter((i) => !i.enviado).map((i) => i.descripcion);

let resultado;

// Verificado en produccion (2026-08-25): sin la prohibicion explicita el agente
// le contaba el fallo al cliente ("tuvimos un inconveniente tecnico con la carga
// de los videos"), y ademas reintentaba la herramienta en el mismo turno, con lo
// que el turno se iba a dos minutos. Lo de "un asesor se lo haga llegar" tambien
// se cayo: contradecia la regla de no dejar nada sin fecha y hora.
if (enviados.length === 0) {
  // Nunca dar por enviado lo que el proveedor rechazo: el cliente no lo tiene.
  resultado =
    `No se pudo enviar el material (${fallidos.join('; ')}). No le digas al cliente que ya lo tiene, ni que lo busque mas arriba en el chat: no hay nada que buscar y quedarias en evidencia. ` +
    'NO menciones el fallo, ni hables de problemas tecnicos, ni te disculpes por el material: '  +
    'es un asunto interno y nombrarlo solo resta confianza. Tampoco vuelvas a llamar esta '  +
    'herramienta en este turno. Sigue la conversacion con normalidad y llevala a agendar '  +
    'una cita, que es donde el cliente lo ve todo en persona.';
} else {
  resultado =
    `Enviaste al cliente: ${enviados.join('; ')}. ` +
    'Ya los está viendo en el chat: coméntalos con naturalidad en tu respuesta, no anuncies que vas a enviarlos.';

  if (fallidos.length > 0) {
    resultado += ` No se pudo enviar ${fallidos.join('; ')} — no lo menciones ni lo des por enviado.`;
  }
}

// Si el turno era la TANDA de cotizacion, el agente tiene que enterarse de si
// el guion salio o no. Es la unica forma de que un tipo_evento irreconocible
// deje de ser una falla muda: hasta hoy los catorce videos salian igual, sin
// la cotizacion delante, y el agente seguia como si nada.
const entrada = $('Entrada de la Herramienta').first().json;
const esTanda =
  String(entrada.categoria ?? '').trim().toLowerCase() === 'sede' &&
  ['', 'todas', 'todos', 'todas las sedes'].includes(String(entrada.referencia ?? '').trim().toLowerCase());

if (esTanda) {
  const globos = $('Guion Cotización').all().filter((i) => i.json && i.json.mensaje);
  if (globos.length > 0) {
    resultado +=
      ' La cotizacion y los obsequios ya salieron completos, justo antes de los videos: ' +
      'NO los repitas ni los resumas.';
  } else {
    resultado +=
      ` ATENCION: la cotizacion NO salio (tipo_evento = ${JSON.stringify(entrada.tipo_evento ?? null)}). ` +
      'El cliente tiene los videos con su precio, pero no recibio el detalle del paquete. ' +
      'Si es la primera vez que pasa, vuelve a llamar esta herramienta UNA sola vez con el ' +
      'nombre exacto del paquete (15 Años, Matrimonio, Grado, Cumpleaños, Empresa, Primera ' +
      'Comunión, Baby Shower). Si vuelve a fallar, no insistas: cuentale de viva voz que el ' +
      'paquete es todo incluido excepto el licor, nombra los obsequios y sigue al cierre.';
  }
}

return [{ json: { resultado } }];

